SELECT 
  purchase_header.purchase_id,
  purchase_header.purchase_date,
  supplier.supplier_name,
  purchase_header.total_amount
FROM purchase_header
LEFT JOIN supplier USING (supplier_id)
ORDER BY {{data_table.sortOrder.column || 'purchase_id'}} {{data_table.sortOrder.order || "ASC"}}
LIMIT {{data_table.pageSize}}
OFFSET {{(data_table.pageNo - 1) * data_table.pageSize}};
